import functools
import jax
import jax.numpy as jnp
from jax import lax
from jax.experimental import pallas as pl
from jax.experimental.pallas import tpu as pltpu

IGNORE_INDEX = 0.0
C_SCALE = 0.2


def _pick(n, cap, mult):
    if n <= cap:
        return n
    for t in range(cap, 0, -1):
        if n % t == 0 and t % mult == 0:
            return t
    return n


def _ih_kernel(x_ref, t_ref, out_ref, mx_ref, acc_ref, *, ch, inv_n):
    f32 = jnp.float32
    phase = pl.program_id(0)
    i = pl.program_id(1)
    last = pl.num_programs(1) - 1
    tm, lanes = x_ref.shape
    nch = tm // ch

    @pl.when((phase == 0) & (i == 0))
    def _():
        mx_ref[...] = jnp.zeros_like(mx_ref)       # err >= 0, so 0 is a safe max identity
        acc_ref[...] = jnp.zeros_like(acc_ref)

    def load(j):
        r = pl.multiple_of(j * ch, ch)
        x = x_ref[pl.ds(r, ch), :].astype(f32)
        t = t_ref[pl.ds(r, ch), :].astype(f32)
        diff = jnp.maximum(x, 0.0) - t
        mask = (t != IGNORE_INDEX).astype(f32)
        return diff, jnp.abs(diff * mask)

    @pl.when(phase == 0)
    def _():
        def body(j, m):
            _, err = load(j)
            return jnp.maximum(m, err.reshape(ch // 8, 8, lanes).max(axis=0))
        mx_ref[...] = jnp.maximum(mx_ref[...], lax.fori_loop(0, nch, body, jnp.zeros((8, lanes), f32)))

    @pl.when(phase == 1)
    def _():
        c = C_SCALE * jnp.max(mx_ref[...], keepdims=True)        # (1, 1)
        c2 = c * c
        inv2c = 1.0 / (2.0 * c)

        def body(j, acc):
            diff, err = load(j)
            err2 = (diff * diff + c2) * inv2c
            v = err * (err <= c).astype(f32) + err2 * (err > c).astype(f32)
            return acc + v.reshape(ch // 8, 8, lanes).sum(axis=0)

        acc_ref[...] += lax.fori_loop(0, nch, body, jnp.zeros((8, lanes), f32))

        @pl.when(i == last)
        def _():
            out_ref[...] = jnp.sum(acc_ref[...], keepdims=True) * inv_n


def workload(x, target):
    lanes = x.shape[-1]
    m = x.size // lanes
    tm = _pick(m, 2048, 8)
    ch = _pick(tm, 64, 8)
    res = pl.pallas_call(
        functools.partial(_ih_kernel, ch=ch, inv_n=1.0 / x.size),
        out_shape=jax.ShapeDtypeStruct((1, 1), jnp.float32),
        grid=(2, m // tm),
        in_specs=[pl.BlockSpec((tm, lanes), lambda p, i: (i, 0)),
                  pl.BlockSpec((tm, lanes), lambda p, i: (i, 0))],
        out_specs=pl.BlockSpec((1, 1), lambda p, i: (0, 0)),
        scratch_shapes=[pltpu.VMEM((8, lanes), jnp.float32), pltpu.VMEM((8, lanes), jnp.float32)],
        compiler_params=pltpu.CompilerParams(dimension_semantics=("arbitrary", "arbitrary")),
    )(x.reshape(m, lanes), target.reshape(m, lanes))
    return res.reshape(()).astype(x.dtype)

