import jax
import jax.numpy as jnp
from jax import lax
from jax.experimental import pallas as pl
from jax.experimental.pallas import tpu as pltpu


def _pick(n, cap, mult):
    if n <= cap:
        return n
    for t in range(cap, 0, -1):
        if n % t == 0 and t % mult == 0:
            return t
    return n


def _lr_kernel(x_ref, w_ref, bl_ref, bias_ref, o_ref, s_ref, *, d1_total):
    # out[d2] = bias + D1*b_lin + sum_f (sum_d1 x[d1, d2, f]) * w[f]; the d1 sum is pure vector adds.
    f32 = jnp.float32
    k = pl.program_id(1)
    td1 = x_ref.shape[1]

    @pl.when(k == 0)
    def _():
        s_ref[...] = jnp.zeros_like(s_ref)

    def body(d, acc):
        return acc + x_ref[0, d].astype(f32)

    s_ref[...] += lax.fori_loop(0, td1, body, jnp.zeros(s_ref.shape, f32))

    @pl.when(k == pl.num_programs(1) - 1)
    def _():
        y = jnp.sum(s_ref[...] * w_ref[...].astype(f32), axis=-1, keepdims=True)   # (D2, 1), exact f32
        const = bias_ref[...].astype(f32) + d1_total * bl_ref[...].astype(f32)
        o_ref[0] = (y + const).astype(o_ref.dtype)


def workload(x, w, b_lin, bias):
    b, d1, d2, f = x.shape
    o = w.shape[1]   # output_dim == 1 in this module
    td1 = _pick(d1, 32, 1)
    out = pl.pallas_call(
        functools.partial(_lr_kernel, d1_total=float(d1)),
        out_shape=jax.ShapeDtypeStruct((b, d2, o), x.dtype),
        grid=(b, d1 // td1),
        in_specs=[pl.BlockSpec((1, td1, d2, f), lambda i, k: (i, k, 0, 0)),
                  pl.BlockSpec((1, f), lambda i, k: (0, 0)),
                  pl.BlockSpec((1, 1), lambda i, k: (0, 0)),
                  pl.BlockSpec((1, 1), lambda i, k: (0, 0))],
        out_specs=pl.BlockSpec((1, d2, o), lambda i, k: (i, 0, 0)),
        scratch_shapes=[pltpu.VMEM((d2, f), jnp.float32)],
        compiler_params=pltpu.CompilerParams(dimension_semantics=("parallel", "arbitrary")),
    )(x, w.reshape(1, f), b_lin.reshape(1, 1), bias.reshape(1, 1))
    return out.reshape(b, 1, d2, o)

